import{_ as a,o as i,c as s,aj as t}from"./chunks/framework.C6uXqnaX.js";const c=JSON.parse('{"title":"Runtime Performance Warnings","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG0913.md","filePath":"en/errors/NG0913.md"}'),n={name:"en/errors/NG0913.md"};function r(l,e,o,d,h,g){return i(),s("div",null,e[0]||(e[0]=[t(`<h1 id="runtime-performance-warnings" tabindex="-1">Runtime Performance Warnings <a class="header-anchor" href="#runtime-performance-warnings" aria-label="Permalink to &quot;Runtime Performance Warnings&quot;">​</a></h1><h3 id="oversized-images" tabindex="-1">Oversized images <a class="header-anchor" href="#oversized-images" aria-label="Permalink to &quot;Oversized images&quot;">​</a></h3><p>When images are loaded, the <strong>intrinsic size</strong> of the downloaded file is checked against the actual size of the image on the page. The actual size is calculated using the <strong>rendered size</strong> of the image with CSS applied, multiplied by the <a href="https://web.dev/codelab-density-descriptors/#pixel-density" target="_blank" rel="noreferrer">pixel device ratio</a>. If the downloaded image is much larger (more than 1200px too large in either dimension), this warning is triggered. Downloading oversized images can slow down page loading and have a negative effect on <a href="https://web.dev/vitals/" target="_blank" rel="noreferrer">Core Web Vitals</a>.</p><h3 id="lazy-loaded-lcp-element" tabindex="-1">Lazy-loaded LCP element <a class="header-anchor" href="#lazy-loaded-lcp-element" aria-label="Permalink to &quot;Lazy-loaded LCP element&quot;">​</a></h3><p>The largest contentful element on a page during load is considered the &quot;LCP Element&quot;, which relates to <a href="https://web.dev/lcp/" target="_blank" rel="noreferrer">Largest Contentful Paint</a>, one of the Core Web Vitals. Lazy loading an LCP element will have a strong negative effect on page performance. With this strategy, the browser has to complete layout calculations to determine whether the element is in the viewport before starting the image download. As a result, a warning is triggered when Angular detects that the LCP element has been given the <code>loading=&quot;lazy&quot;</code> attribute.</p><h3 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h3><p>Use the image URL provided in the console warning to find the <code>&lt;img&gt;</code> element in question.</p><h3 id="ways-to-fix-oversized-images" tabindex="-1">Ways to fix oversized images <a class="header-anchor" href="#ways-to-fix-oversized-images" aria-label="Permalink to &quot;Ways to fix oversized images&quot;">​</a></h3><ul><li>Use a smaller source image</li><li>Add a <a href="https://web.dev/learn/design/responsive-images/#responsive-images-with-srcset" target="_blank" rel="noreferrer"><code>srcset</code></a> if multiple sizes are needed for different layouts.</li><li>Switch to use Angular&#39;s built-in image directive (<a href="https://angular.dev/api/common/NgOptimizedImage" target="_blank" rel="noreferrer"><code>NgOptimizedImage</code></a>), which generates <a href="/en/guide/image-optimization#request-images-at-the-correct-size-with-automatic-srcset">srcsets automatically</a>.</li></ul><h3 id="ways-to-fix-lazy-loaded-lcp-element" tabindex="-1">Ways to fix lazy-loaded LCP element <a class="header-anchor" href="#ways-to-fix-lazy-loaded-lcp-element" aria-label="Permalink to &quot;Ways to fix lazy-loaded LCP element&quot;">​</a></h3><ul><li>Change the <code>loading</code> attribute to a different value such as <code>&quot;eager&quot;</code>.</li><li>Switch to use Angular&#39;s built-in image directive (<a href="https://angular.dev/api/common/NgOptimizedImage" target="_blank" rel="noreferrer"><code>NgOptimizedImage</code></a>), which allows for easily <a href="/en/guide/image-optimization#mark-images-as-priority">prioritizing LCP images</a>.</li></ul><h3 id="disabling-image-performance-warnings" tabindex="-1">Disabling Image Performance Warnings <a class="header-anchor" href="#disabling-image-performance-warnings" aria-label="Permalink to &quot;Disabling Image Performance Warnings&quot;">​</a></h3><p>Both warnings can be disabled individually, site-wide, using a provider at the root of your application:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    provide: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">IMAGE_CONFIG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    useValue: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      disableImageSizeWarning: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      disableImageLazyLoadWarning: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div>`,14)]))}const m=a(n,[["render",r]]);export{c as __pageData,m as default};
